/* eslint-disable */
// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
  Easing,
  interpolateColors
} from '../remotionShim';
// Google Fonts — module-level loadFont calls
import { makeLoadFont } from '../googleFonts';
const loadMontserrat = makeLoadFont('Montserrat');
const loadPlayfairDisplay = makeLoadFont('PlayfairDisplay');

const { fontFamily: montserratFamily } = loadMontserrat();
const { fontFamily: playfairFamily } = loadPlayfairDisplay();



export type CondensingBoxesProps = Record<string, any>;

const CondensingBoxes: React.FC<CondensingBoxesProps> = ({
  backgroundColor = "#050505",
  transparentBackground = false,
  durationInSeconds = 5,
  boxColor = "#FFA3B1", // Pink
  finalBoxColor = "#261817", // Dark Brown
  initialText = "C",
  finalTitle = "CRAVED",
  finalSubtitle = "THIS.",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Responsive Math calculations
  const s = Math.min(width, height);
  const cx = width / 2;
  const cy = height / 2;

  // Box size configurations
  const boxWidth = s * 0.22;
  const boxHeight = s * 0.18;
  const maxR = s * 0.32;
  const finalWidth = s * 0.75;
  const finalHeight = s * 0.85;
  const initialRadius = s * 0.015;
  const finalRadius = s * 0.03;

  // Global hold scale to keep scene alive after animation
  const maxFrames = fps * durationInSeconds;
  const holdScale = interpolate(frame, [120, Math.max(121, maxFrames)], [1, 1.05], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Phases of the animation
  // 1. Rotation of the 3 boxes
  const rotation = interpolate(frame, [20, 90], [0, Math.PI * 2], {
    easing: Easing.inOut(Easing.cubic),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // 2. Condensing radius (boxes merge into center)
  const radius = interpolate(frame, [50, 90], [maxR, 0], {
    easing: Easing.inOut(Easing.cubic),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // 3. Merged Box Expansion Factor (0 to 1)
  const expandFactor = interpolate(frame, [90, 120], [0, 1], {
    easing: Easing.inOut(Easing.cubic),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Dynamic values for the Merged Box during expansion
  const currentMergedWidth = interpolate(expandFactor, [0, 1], [boxWidth, finalWidth]);
  const currentMergedHeight = interpolate(expandFactor, [0, 1], [boxHeight, finalHeight]);
  const currentMergedColor = interpolateColors(expandFactor, [0, 1], [boxColor, finalBoxColor]);
  const currentMergedRadius = interpolate(expandFactor, [0, 1], [initialRadius, finalRadius]);
  const currentShadow = interpolate(expandFactor, [0, 1], [s * 0.005, s * 0.02]);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, justifyContent: "center", alignItems: "center" }}>
      <AbsoluteFill style={{ transform: `scale(${holdScale})`, transition: "none" }}>
        
        {/* Phase 1: The 3 separate boxes revolving and condensing */}
        {frame < 90 &&
          [0, 1, 2].map((i) => {
            const boxScale = spring({
              frame: frame - i * 5,
              fps,
              config: { damping: 12 },
            });

            const angle = (i * 2 * Math.PI) / 3 - Math.PI / 2 + rotation;
            const x = cx + radius * Math.cos(angle) - boxWidth / 2;
            const y = cy + radius * Math.sin(angle) - boxHeight / 2;

            return (
              <div
                key={i}
                style={{
                  position: "absolute",
                  left: x,
                  top: y,
                  width: boxWidth,
                  height: boxHeight,
                  backgroundColor: boxColor,
                  borderRadius: initialRadius,
                  display: "flex",
                  justifyContent: "center",
                  alignItems: "center",
                  transform: `scale(${boxScale})`,
                  boxShadow: `0 ${s * 0.005}px ${s * 0.01}px rgba(0,0,0,0.3)`,
                  transition: "none",
                }}
              >
                <span
                  style={{
                    fontFamily: playfairFamily,
                    fontStyle: "italic",
                    fontSize: boxHeight * 0.6,
                    color: finalBoxColor,
                    fontWeight: "bold",
                    lineHeight: 1,
                    transition: "none",
                  }}
                >
                  {initialText}
                </span>
              </div>
            );
          })}

        {/* Phase 2: The single merged box that replaces the 3 boxes exactly when they overlap */}
        {frame >= 90 && (
          <div
            style={{
              position: "absolute",
              left: cx - currentMergedWidth / 2,
              top: cy - currentMergedHeight / 2,
              width: currentMergedWidth,
              height: currentMergedHeight,
              backgroundColor: currentMergedColor,
              borderRadius: currentMergedRadius,
              display: "flex",
              flexDirection: "column",
              justifyContent: "center",
              alignItems: "center",
              boxShadow: `0 ${currentShadow / 2}px ${currentShadow}px rgba(0,0,0,0.5)`,
              overflow: "hidden",
              transition: "none",
            }}
          >
            {/* Faint aesthetic symbols in the background of the box */}
            <div
              style={{
                position: "absolute",
                opacity: interpolate(expandFactor, [0.2, 1], [0, 0.08], {
                  extrapolateLeft: "clamp",
                  extrapolateRight: "clamp",
                }),
                display: "flex",
                justifyContent: "center",
                alignItems: "center",
                width: "100%",
                height: "100%",
                fontSize: currentMergedWidth * 0.6,
                color: boxColor,
                fontFamily: montserratFamily,
                gap: currentMergedWidth * 0.1,
                transition: "none",
                pointerEvents: "none",
              }}
            >
              <span>♂</span>
              <span>♀</span>
            </div>

            {/* Seamless fade out of the initial shared letter "C" */}
            <div
              style={{
                position: "absolute",
                opacity: interpolate(expandFactor, [0, 0.2], [1, 0], { extrapolateRight: "clamp" }),
                fontFamily: playfairFamily,
                fontStyle: "italic",
                fontSize: boxHeight * 0.6,
                color: finalBoxColor,
                fontWeight: "bold",
                lineHeight: 1,
                transition: "none",
              }}
            >
              {initialText}
            </div>

            {/* Final Text Reveal */}
            <div
              style={{
                opacity: interpolate(expandFactor, [0.3, 1], [0, 1], {
                  extrapolateLeft: "clamp",
                  extrapolateRight: "clamp",
                }),
                transform: `translateY(${interpolate(expandFactor, [0.3, 1], [s * 0.03, 0], {
                  extrapolateLeft: "clamp",
                  extrapolateRight: "clamp",
                })}px)`,
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
                transition: "none",
                zIndex: 2,
              }}
            >
              <span
                style={{
                  fontFamily: montserratFamily,
                  fontWeight: 900,
                  fontSize: currentMergedWidth * 0.16,
                  color: boxColor,
                  letterSpacing: "0.05em",
                  lineHeight: 1,
                  transition: "none",
                }}
              >
                {finalTitle}
              </span>
              <span
                style={{
                  fontFamily: montserratFamily,
                  fontWeight: 600,
                  fontSize: currentMergedWidth * 0.08,
                  color: boxColor,
                  letterSpacing: "0.1em",
                  marginTop: s * 0.005,
                  transition: "none",
                }}
              >
                {finalSubtitle}
              </span>
            </div>
          </div>
        )}
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default CondensingBoxes;